entries[8797] = { ["name"] = "Buch der Verjüngung X", ["text"] = "Klassen: Druide\nBenötigt Stufe 58\n\"Lehrt 'Verjüngung' (Rang 4).\"\nVerkaufspreis:" }
entries[8798] = { ["name"] = "Buch des Sternenfeuers VI", ["text"] = "Klassen: Druide\nBenötigt Stufe 58\nBenutzen: Lehrt 'Mondfeuer' (Rang 6).\nVerbrennt den Feind mit 1 Arkanschaden und verursacht zusätzlich im Verlauf von 12 Sek. weitere ( 0 * 6) Arkanschaden.\nVerkaufspreis:" }
entries[8799] = { ["name"] = "Buch des Mals der Wildnis VII", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\n\"Lehrt 'Mal der Wildnis' (Rang 4).\"\nVerkaufspreis:" }
entries[8800] = { ["name"] = "Buch des Nachwachsens IX", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verjüngung' (Rang 1).\nHeilt ein befreundetes Ziel um 0 sowie zusätzlich im Verlauf von 6 Sek. um insgesamt [Quellwert]. [ Glyphe 'Nachwachsen' : Die Effektdauer von 'Nachwachsen' wird jedes Mal, wenn der Zauber ein Ziel mit 50% Gesundheit oder weniger heilt, automatisch auf 6 Sek. zurückgesetzt ] [ Baum des Lebens : Baum des Lebens: Spontanzauber. ]\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[8801] = { ["name"] = "Buch der Gelassenheit IV", ["text"] = "Klassen: Druide\nBenötigt Stufe 60\nBenutzen: Lehrt 'Gelassenheit' (Rang 1).\nHeilt die 5 Gruppen- oder Schlachtzugsmitglieder im Umkreis von 40 Metern, deren Gesundheit am niedrigsten ist, 8 Sek. lang alle 2 Sek. um 0 Gesundheit.\n\nZusätzlich heilt 'Gelassenheit' 8 Sek. lang alle 2 Sek. um 0 Gesundheit. Bis zu 3-mal stapelbar. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten.\nVerkaufspreis:" }
