entries[8804] = { ["name"] = "Foliant der arkanen Explosion", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nFeuert im Verlauf von 2.25 Sek. [4][3] Wellen arkaner Geschosse auf einen Feind ab, welche pro Welle 16 Arkanschaden verursachen. Jeder von Euch gewirkte Offensivzauber hat eine Chance von 40%, 'Arkane Geschosse' auszulösen.\nVerkaufspreis:" }
