entries[8889] = { ["name"] = "Foliant des Manaedelsteinherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 58\nBenutzen: Lehrt 'Manaedelstein herbeizaubern'.\nZaubert einen Manaedelstein herbei, der zum sofortigen Wiederherstellen von 984 Mana verwendet werden kann.\nVerkaufspreis:\nManaedelstein\nWird beim Aufheben gebunden\nEinzigartig: [Mana Gem] (1)\nBenutzen: Stellt 12103 Mana wieder her. (2 Min Abklingzeit)\n3 Aufladungen" }
