entries[8898] = { ["name"] = "Foliant der arkanen Explosion IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 38\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nFeuert im Verlauf von 2.25 Sek. [4][3] Wellen arkaner Geschosse auf einen Feind ab, welche pro Welle 40 Arkanschaden verursachen. Jeder von Euch gewirkte Offensivzauber hat eine Chance von 40%, 'Arkane Geschosse' auszulösen.\nVerkaufspreis:" }
