entries[9030] = { ["name"] = "Regenerationstrank", ["text"] = "Benötigt Stufe 32\nBenutzen: Versucht 30 Sek. Sekunden lang alle 5 Sek. einen magischen, Fluch-, Gift- oder Krankheitseffekt aufzuheben, der auf Euch wirkt.\n\nErfolgsschance ist gegen Effekte, die von Gegnern über Stufe 42 verursacht wurden, reduziert. (1 Min Abklingzeit)\nVerkaufspreis:" }
