entries[9036] = { ["name"] = "Magiewiderstandstrank", ["text"] = "Benötigt Stufe 32\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 3 Min. lang um 50. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[9037] = { ["name"] = "Schrifttafel der Waffe des Felsbeißers", ["text"] = "Klassen: Schamane\n\"Lehrt 'Blitzschlag' (Rang 2).\"\nVerkaufspreis:" }
entries[9039] = { ["name"] = "Schrifttafel des Erdschocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Totem der Schlange' (Rang 1).\nBeschwört 1 Min. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das einen Feind im Umkreis von 20 Metern mehrfach angreift und ihm 3 Feuerschaden zufügt. Das Totem greift bevorzugt Gegner an, die von Euren Effekten 'Flammenschock' oder 'Sturmschlag' getroffen wurden.\nVerkaufspreis:" }
entries[9040] = { ["name"] = "Schrifttafel der Welle der Heilung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\n\"Lehrt 'Schmelzschlag' (Rang 1).\"\nVerkaufspreis:" }
entries[9041] = { ["name"] = "Schrifttafel des Totems der Erdbindung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Erdbindung'.\nBeschwört ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt. Hält 45 Sek. lang an.\nVerkaufspreis:" }
entries[9043] = { ["name"] = "Schrifttafel des Totems der Steinklaue", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 1).\nBeschwört ein Totem der Steinklaue mit 98 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden. Das Totem der Steinklaue beschützt auch all Eure anderen Totems mit einem Schild, der 65 Schaden absorbiert [ Glyphe 'Totem der Steinklaue' : und gewährt dem Zaubernden zusätzlich einen Schild, der bis zu ( 65 * 4) Schaden absorbiert ]. Das Totem hält 15 Sek. lang an.\nVerkaufspreis:" }
entries[9044] = { ["name"] = "Schrifttafel des Erdschocks II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde wird von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifer 12 Naturschaden. Dies kostet einen Kugelblitz [ Glyphe 'Blitzschlagschild' : wird die Anzahl der Aufladungen jedoch nicht unter 3 senken ]. Es kann immer nur ein einzelner Kugelblitz alle paar Sekunden ausgelöst werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)\nVerkaufspreis:" }
entries[9046] = { ["name"] = "Schrifttafel des Totems der Erdstärke", ["text"] = "Klassen: Schamane\nBenötigt Stufe 10\nBenutzen: Lehrt 'Totem der Schlange' (Rang 1).\nBeschwört 1 Min. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das einen Feind im Umkreis von 20 Metern mehrfach angreift und ihm 3 Feuerschaden zufügt. Das Totem greift bevorzugt Gegner an, die von Euren Effekten 'Flammenschock' oder 'Sturmschlag' getroffen wurden.\nVerkaufspreis:" }
