entries[9190] = { ["name"] = "Zauberfoliant des Feuerbrandes", ["text"] = "Klassen: Hexenmeister\n\"Lehrt 'Feuerbrand' (Rang 2).\"\nVerkaufspreis:" }
entries[9191] = { ["name"] = "Zauberfoliant des Fluchs der Schwäche", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 4\nBenutzen: Lehrt 'Fluch der Sprachen' (Rang 1).\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 30%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[9192] = { ["name"] = "Zauberfoliant der Verderbnis", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 4\nBenutzen: Lehrt 'Verderbnis' (Rang 1).\nVerdirbt das Ziel und verursacht 18 Sek. lang insgesamt 23 Schattenschaden.\nVerkaufspreis:" }
entries[9193] = { ["name"] = "Zauberfoliant des Aderlasses", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 6\n\"Lehrt 'Schattenblitz' (Rang 2).\"\nVerkaufspreis:" }
entries[9194] = { ["name"] = "Zauberfoliant des Fluchs der Pein", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 8\nBenutzen: Lehrt 'Fluch der Pein' (Rang 1).\nVerflucht das Ziel mit Pein und verursacht im Verlauf von 24 Sek. 45 Schattenschaden. Zunächst wird der Schaden langsam verursacht und er steigt an, bis das Omen seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Omen pro Hexenmeister auf einem beliebigen Ziel aktiv sein.\nVerkaufspreis:" }
entries[9195] = { ["name"] = "Zauberfoliant des Seelenabziehens", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 10\nBenutzen: Lehrt 'Furcht' (Rang 1).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 20 Sek. lang [ Glyphe 'Furcht' : vor Furcht erstarrt / voller Furcht flüchtet]. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden.\nVerkaufspreis:" }
entries[9197] = { ["name"] = "Elixier der Traumvision", ["text"] = "Benötigt Stufe 38\nBenutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[9198] = { ["name"] = "Zauberfoliant der Lebenslinie", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nOpfert 1 % Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6 % seiner gesamten Gesundheit zu heilen. Hält 3 Sek. lang an.\nVerkaufspreis:" }
entries[9199] = { ["name"] = "Zauberfoliant des Fluchs der Tollkühnheit", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nOpfert 1 % Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6 % seiner gesamten Gesundheit zu heilen. Hält 3 Sek. lang an.\nVerkaufspreis:" }
entries[9200] = { ["name"] = "Zauberfoliant des Fluchs der Schwäche II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Blutsauger' (Rang 1).\nEntzieht dem Ziel das Leben. Verursacht alle 1 Sek. 3 Schattenschaden und stellt 2% der gesamten Gesundheit des Zaubernden wieder her. Hält 3 Sek. lang an. [ Seelenbrand : Seelenbrand: Zauberzeit um 50% verringert. ]\nVerkaufspreis:" }
entries[9201] = { ["name"] = "Zauberfoliant der Verderbnis II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 16\n\"Lehrt 'Verderbnis' (Rang 2).\"\nVerkaufspreis:" }
entries[9202] = { ["name"] = "Zauberfoliant des Aderlasses II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 18\nBenutzen: Lehrt 'Seelenstein herstellen'.\nErschafft einen Seelenstein, in dem die Seele eines Ziels gespeichert werden kann. Wird die Seele eines lebendigen Ziels gespeichert, kann es sich nach seinem Tod wiederbeleben. Wird der Seelenstein auf ein totes Ziel gewirkt, wird es sofort wiederbelebt. In beiden Fällen werden Ziele mit 30% Gesundheit und 30% Mana wiederbelebt.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nSeelenstein\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erschafft einen Seelenstein, in dem die Seele eines Ziels gespeichert werden kann. Wird die Seele eines lebendigen Ziels gespeichert, kann es sich nach seinem Tod wiederbeleben. Wird der Seelenstein auf ein totes Ziel gewirkt, wird es sofort wiederbelebt. In beiden Fällen werden Ziele mit 30% Gesundheit und 30% Mana wiederbelebt." }
entries[9203] = { ["name"] = "Zauberfoliant des Rituals der Beschwörung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Feuerregen' (Rang 1).\nLässt einen feurigen Regen niedergehen, der 8 Sek. lang Feinde im Wirkungsbereich mit insgesamt ( 43 * 4) Feuerschaden verbrennt.\nVerkaufspreis:" }
