entries[9303] = { ["name"] = "Rezept: Stein der Weisen", ["text"] = "Benötigt Alchemie\n(225)\nBenutzen: Lehrt Euch die Herstellung eines Steins der Weisen.\nVerkaufspreis:\nStein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\n+5 Beweglichkeit\n+5 Ausdauer\n+5 Intelligenz\n+5 Willenskraft\nBenötigt Stufe 35\nBenötigt Alchemie\n(200)\n\"Erforderlich für alchemistische Transmutation.\"\nVerkaufspreis:\nBenötigt Eisenbarren (4), Schwarzes Vitriol , Lila Lotus (4), Feuerblüte (4)" }
